// Server-side translations: the questions, their options, the catalogue's descriptions and the recommender's
// sentences. The bot UI's own copy is in ./ui.ts. Translations are generated by `npm run translate` into
// data/locales/content/<lang>.json; English is the source and lives in the code it always has.
import hi from "../../../data/locales/content/hi.json";
import ta from "../../../data/locales/content/ta.json";
import { MESSAGES } from "../recommender/messages";
import { format, lookup, type LocaleFile, type Vars } from "./format";
import type { Lang } from "./languages";

const FILES: Record<Exclude<Lang, "en">, LocaleFile> = { hi, ta };

/** Sentences outside the recommender that the server shows customers. */
export const CONTENT_MESSAGES = {
  ...MESSAGES,
  "interpret.unclear": "Sorry, we didn't quite catch that. Could you answer a little differently?",
  /** For "I don't know" on a question that can't be skipped: the customer was clear, so don't say we misheard. */
  "interpret.needed": "No problem, but we do need this one to suggest the right bundle.",
  "explain.compared": "Compared with the Recommended bundle: {changes}.",
  /** Used for a Budget or Premium bundle when the model's own text can't be trusted. */
  "explain.alternativeFallback": "{label} bundle. {comparison}",
} as const;
export type ContentKey = keyof typeof CONTENT_MESSAGES;

/** Translates `english`, stored under `key`, and fills its placeholders. English comes back unchanged. */
export function translate(lang: Lang, key: string, english: string, vars?: Vars): string {
  return format(lang === "en" ? english : lookup(FILES[lang], key, english), vars);
}

/** One of CONTENT_MESSAGES in the customer's language. */
export const contentMessage = (lang: Lang, key: ContentKey, vars?: Vars) => translate(lang, key, CONTENT_MESSAGES[key], vars);

// Keys for strings that come from the CSVs and the question set.
export const questionKey = (questionId: string) => `question.${questionId}`;
export const hintKey = (questionId: string) => `hint.${questionId}`;
/** Option labels, segment names and cities, keyed by their English text: the same label always reads the same. */
export const labelKey = (english: string) => `label.${english}`;
export const descriptionKey = (productId: string) => `description.${productId}`;

export const translateLabel = (lang: Lang, english: string) => translate(lang, labelKey(english), english);
